# 其他名篇的赏析（原创撰写）。f = 首句前几个字，用来在诗名写法不同时（如「鼓吹曲辞 将进酒」）也能对上
N = {
"将进酒|李白": dict(f="君不见黄河", yi="黄河之水从天上奔流入海，一去不回；人的青春也像早晨的黑发，到晚上就变白了。人生得意时就要尽情欢乐，天生我材必有用，千金散尽还会再来。诗人劝朋友们畅饮，把满腔的愁绪都化在酒里。", qing="豪放洒脱，又带着怀才不遇的苦闷。", ci={"君不见":"你没有看见吗","樽":"酒杯","岑夫子、丹丘生":"李白的两位朋友岑勋、元丹丘"}),
"蜀道难|李白": dict(f="噫吁嚱危乎", yi="诗人用神话、传说和极度夸张的描写，写出入蜀道路的高险艰难：山高到太阳神的车都要绕道，黄鹤飞不过，猿猴攀不上。", qing="惊叹山川的雄奇险峻。", ci={"噫吁嚱":"惊叹声","蚕丛、鱼凫":"传说中古蜀国的两位君王"}),
"行路难（其一）|李白": dict(f="金樽清酒斗", yi="面对美酒佳肴却吃不下，拔出宝剑四处张望，心里一片茫然。想渡黄河，冰塞住了河道；想登太行，大雪封了山。人生道路多么艰难！但总有一天会乘长风破巨浪，挂起云帆渡过大海。", qing="在迷茫中仍然相信未来。", ci={"珍羞":"珍贵的菜肴","直":"同「值」","济":"渡过"}),
"月下独酌（其一）|李白": dict(f="花间一壶酒", yi="花丛中摆着一壶酒，独自喝没有朋友陪伴。举起杯邀请明月，加上自己的影子，就成了三个人。", qing="在孤独中自得其乐，想象浪漫。", ci={"酌":"喝酒","三人":"指月、我和影子"}),
"闻王昌龄左迁龙标遥有此寄|李白": dict(f="杨花落尽子", yi="杨花落尽、杜鹃哀啼的时节，听说你被贬到龙标，要经过五条溪水。我把忧愁的心托付给明月，让它随着风一直陪你到夜郎以西。", qing="对朋友遭贬的同情和关切。", ci={"左迁":"降职","子规":"杜鹃鸟","夜郎":"古地名，在今贵州、湖南一带"}),
"渡荆门送别|李白": dict(f="渡远荆门外", yi="我坐船远渡到荆门之外，来到楚国故地游览。山随着平原的出现渐渐消失，江水流进广阔的原野。月影像天上飞下的明镜，云彩变幻成海市蜃楼。我依然怜爱故乡的江水，它不远万里送我的船远行。", qing="初出蜀地的开阔心胸，也有对故乡的眷恋。", ci={"荆门":"荆门山，在今湖北宜都","海楼":"海市蜃楼"}),
"送友人|李白": dict(f="青山横北郭", yi="青山横在北城外，白水绕着东城流。在这里分别后，你就像蓬草一样要飘到万里之外。浮云像游子的心意，落日像老朋友的情谊。挥手告别，马儿也萧萧长鸣。", qing="依依惜别之情。", ci={"郭":"外城","孤蓬":"随风飘转的蓬草，比喻远行的人","萧萧":"马叫声"}),
"春夜洛城闻笛|李白": dict(f="谁家玉笛暗", yi="谁家的玉笛在夜里悄悄吹响，乐声随着春风传遍了洛阳城。在这个夜晚听到《折杨柳》的曲子，谁能不生起思念故乡的情怀呢？", qing="春夜闻笛，引起浓浓乡愁。", ci={"暗飞声":"声音悄悄传来","折柳":"指《折杨柳》曲，古人折柳送别"}),
"秋浦歌（其十五）|李白": dict(f="白发三千丈", yi="白发有三千丈长，因为愁绪也这么长。不知道在明亮的镜子里，我是从哪里染上了这一头秋霜般的白发。", qing="用极度夸张写出深深的忧愁。", ci={"缘":"因为","秋霜":"比喻白发"}),
"独坐敬亭山|李白": dict(f="众鸟高飞尽", yi="鸟儿都高高飞走了，最后一片白云也悠闲地飘走了。互相看着永远不会厌倦的，只有我和敬亭山。", qing="孤独中与山为友，寂寞又超然。", ci={"闲":"悠闲","厌":"满足，厌倦"}),
"峨眉山月歌|李白": dict(f="峨眉山月半", yi="峨眉山上挂着半轮秋月，月影倒映在平羌江水中随波流动。夜里我从清溪出发去三峡，想念你却见不到，只好顺流而下到渝州。", qing="初离故乡，对故乡山月的留恋。", ci={"半轮秋":"半圆的秋月","平羌":"江名，即青衣江"}),
"春望|杜甫": dict(f="国破山河在", yi="国都沦陷，只有山河依旧；春天的长安城里草木长得又深又乱。感伤时局，看到花开也会落泪；怨恨离别，听到鸟叫也会心惊。战火连着三个月不停，一封家书抵得上万两黄金。白发越搔越少，简直插不住簪子了。", qing="忧国思家，沉痛深切。", bei="安史之乱中，杜甫被困在叛军占领的长安时所作。", ci={"国":"国都，指长安","烽火":"战火","簪":"古人用来固定头发的簪子"}),
"登高|杜甫": dict(f="风急天高猿", yi="风急天高，猿声凄厉；江中小洲清澈，白沙上鸟儿盘旋。无边的落叶萧萧飘下，看不到头的长江滚滚而来。常年漂泊在外，在秋天登台，一身是病。艰难苦恨让我白发越来越多，最近又因病戒了酒。", qing="悲秋、伤老、思乡、忧国，沉郁顿挫。", bei="杜甫晚年漂泊到夔州时，重阳节登高所作，被誉为「古今七律第一」之一。", ci={"渚":"水中小洲","萧萧":"树叶落下的声音","潦倒":"衰颓失意"}),
"望岳|杜甫": dict(f="岱宗夫如何", yi="泰山是什么样子？它的青色从齐地延伸到鲁地，看不到边。大自然把神奇秀美都集中在这里，山南山北一面明一面暗。看着山中层云升起，胸怀激荡；睁大眼睛看归巢的鸟。总有一天要登上山顶，看群山都显得那么矮小。", qing="青年杜甫的远大志向。", bei="杜甫青年时游历齐鲁、远望泰山时所作。", ci={"岱宗":"泰山","钟":"聚集","会当":"一定要"}),
"闻官军收河南河北|杜甫": dict(f="剑外忽传收", yi="在剑门关外忽然听说官军收复了蓟北，刚听到时泪水洒满衣裳。回头看妻子儿女，愁容一扫而空，随手卷起诗书，高兴得快要发狂。白天放声高歌、尽情喝酒，趁着春光正好结伴还乡。", qing="狂喜之情喷涌而出，被称为杜甫「生平第一快诗」。", bei="作于安史之乱即将结束时，杜甫当时在梓州。", ci={"剑外":"剑门关以南，指四川","漫卷":"随手卷起","青春":"明媚的春光"}),
"月夜忆舍弟|杜甫": dict(f="戍鼓断人行", yi="戍楼上的鼓声响起，路上断了行人，秋天的边塞传来孤雁的叫声。从今夜起就是白露节气，月亮还是故乡的最明亮。兄弟们都分散了，家也没了，无从打听生死。", qing="战乱中思念兄弟的深切忧虑。", ci={"舍弟":"对人谦称自己的弟弟","戍鼓":"戍楼上的更鼓"}),
"江南逢李龟年|杜甫": dict(f="岐王宅里寻", yi="当年在岐王府里常常见到你，在崔九的厅堂前也听过几次你的歌。如今正是江南风景最好的时候，在落花时节又遇见了你。", qing="今昔对比中饱含盛衰之感。", bei="李龟年是开元年间的著名乐师，安史之乱后流落江南，杜甫晚年在潭州遇见他。", ci={"岐王":"唐玄宗的弟弟李范","崔九":"殿中监崔涤"}),
"茅屋为秋风所破歌|杜甫": dict(f="八月秋高风", yi="秋风卷走了屋顶的茅草，孩子们抱着茅草跑了，夜里又下起雨，屋子漏得没有一处干的地方。诗人却想：怎样才能有千万间大房子，让天下贫寒的人都住得开心？", qing="由自己的苦难推及天下人，胸怀博大。", bei="杜甫住在成都草堂时所作。", ci={"三重茅":"几层茅草","广厦":"宽敞的大房子","寒士":"贫寒的读书人"}),
"赠花卿|杜甫": dict(f="锦城丝管日", yi="成都城里每天都弹奏着轻柔的音乐，乐声一半随着江风飘走，一半飘进了云里。这样的曲子只应天上才有，人间能听到几回呢？", qing="赞美乐曲之美，一般认为也含有委婉的讽劝。", ci={"锦城":"成都","丝管":"弦乐器和管乐器"}),
"宿建德江|孟浩然": dict(f="移舟泊烟渚", yi="把船停靠在烟雾笼罩的小洲边，傍晚时分，客中的愁绪又添了几分。原野辽阔，天空好像比树还低；江水清澈，月亮好像离人更近。", qing="羁旅的淡淡愁思。", ci={"渚":"水中小洲","旷":"空旷"}),
"过故人庄|孟浩然": dict(f="故人具鸡黍", yi="老朋友备好了鸡和黄米饭，邀请我到他的田庄做客。绿树环绕着村子，青山在城外斜斜地横着。打开窗子面对打谷场和菜园，喝着酒聊着庄稼。等到重阳节那天，我还要来赏菊花。", qing="田园生活的恬静和朋友间的真情。", ci={"具":"准备","鸡黍":"鸡和黄米饭，指农家饭菜","场圃":"打谷场和菜园","桑麻":"泛指庄稼"}),
"山居秋暝|王维": dict(f="空山新雨后", yi="空旷的山里刚下过一场雨，傍晚的空气带着秋凉。明月照在松林间，清泉在石头上流淌。竹林里传来洗衣女回家的说笑声，莲叶晃动，是渔船顺流而下。春天的芳华尽管消歇了，我仍可以留在山中。", qing="喜爱山居的清幽，向往隐逸。", ci={"暝":"傍晚","浣女":"洗衣服的女子","随意":"任凭","王孙":"贵族子弟，这里指作者自己"}),
"鸟鸣涧|王维": dict(f="人闲桂花落", yi="人很清闲，桂花悄悄飘落，夜晚很安静，春山显得空空荡荡。月亮出来，惊动了山中的鸟，它们不时在山涧里鸣叫。", qing="以动写静，意境幽美。", ci={"涧":"两山之间的流水","春涧":"春天的山涧"}),
"竹里馆|王维": dict(f="独坐幽篁里", yi="独自坐在幽深的竹林里，一会儿弹琴，一会儿长啸。竹林深处没有人知道，只有明月来陪伴我。", qing="悠然自得的隐居情趣。", ci={"幽篁":"幽深的竹林","长啸":"撮口发出悠长的声音"}),
"相思|王维": dict(f="红豆生南国", yi="红豆生长在南方，春天来了又长出多少新枝？希望你多多采摘，这东西最能寄托相思。", qing="借红豆寄托思念。", ci={"南国":"南方","撷":"采摘"}),
"杂诗（其二）|王维": dict(f="君自故乡来", yi="你从故乡来，应该知道故乡的事吧。你来的那天，我家雕花窗前的那株梅花开了没有？", qing="借一株梅花问候故乡，含蓄深情。", ci={"绮窗":"雕画花纹的窗子","著花":"开花"}),
"使至塞上|王维": dict(f="单车欲问边", yi="我轻车简从去慰问边关，经过了居延。像蓬草一样飘出汉家关塞，像归雁一样飞入胡人的天空。大漠里一股孤烟直直升起，长河上落日圆圆的。在萧关遇到侦察的骑兵，说主帅正在燕然前线。", qing="塞外风光壮阔，也有一丝孤寂。", bei="王维奉命出使河西慰问将士时所作。", ci={"单车":"一辆车，指随从不多","征蓬":"随风飘飞的蓬草","候骑":"侦察骑兵"}),
"送杜少府之任蜀州|王勃": dict(f="城阙辅三秦", yi="三秦之地护卫着长安城，遥望着蜀地的五个渡口。和你分别心中有无限感慨，因为我们都是在外做官的人。只要四海之内有知己，即使远在天边也像邻居一样。不要在分手的岔路上，像小儿女那样哭湿手巾。", qing="送别却不伤感，豁达乐观。", ci={"少府":"县尉的别称","宦游":"在外做官","比邻":"近邻","歧路":"岔路"}),
"登幽州台歌|陈子昂": dict(f="前不见古人", yi="往前看不见古代的贤人，往后看不见未来的英才。想到天地无穷无尽，我独自悲伤，流下眼泪。", qing="怀才不遇的孤独与悲怆。", bei="陈子昂随军出征，建议不被采纳，登上幽州台时所作。", ci={"悠悠":"长久遥远的样子","怆然":"悲伤的样子","涕":"眼泪"}),
"黄鹤楼|崔颢": dict(f="昔人已乘黄", yi="传说中的仙人已经乘着黄鹤飞走了，这里只留下空空的黄鹤楼。黄鹤一去不复返，千百年来只有白云悠悠飘荡。晴天里汉阳的树木清晰可见，鹦鹉洲上芳草茂盛。天晚了，故乡在哪里？江上的烟波让人发愁。", qing="怀古之思与思乡之愁。", ci={"昔人":"传说中乘鹤的仙人","历历":"清楚可数","萋萋":"草茂盛的样子"}),
"次北固山下|王湾": dict(f="客路青山外", yi="旅途在青山之外，小船在绿水前航行。潮水上涨，两岸显得更宽阔；顺风正好，船帆高高挂起。夜色还没退尽，海上已升起红日；旧年还没过完，江南已有了春意。寄出的家书怎样送到？请北归的大雁捎到洛阳去吧。", qing="旅途中的思乡情，也有新旧交替的哲理。", ci={"次":"停泊","风正":"顺风","归雁":"北归的大雁"}),
"滁州西涧|韦应物": dict(f="独怜幽草涧", yi="我特别喜爱长在涧边的幽草，树林深处有黄鹂在叫。春潮带着雨水，傍晚流得更急了，荒野的渡口没有人，小船自己横在水面上。", qing="闲适中带着淡淡的忧伤。", bei="韦应物任滁州刺史时所作。", ci={"独怜":"特别喜爱","野渡":"郊野的渡口"}),
"游子吟|孟郊": dict(f="慈母手中线", yi="慈爱的母亲手里拿着针线，为即将远行的孩子缝制衣服。临走前一针一线缝得密密实实，是怕孩子迟迟不能回来。谁说像小草一样微小的孝心，能报答春天阳光般的母爱呢？", qing="歌颂伟大的母爱。", bei="孟郊五十岁时做溧阳县尉，把母亲接来同住时所作。", ci={"游子":"出门远行的人","寸草心":"小草的心意，比喻子女的孝心","三春晖":"春天的阳光，比喻母爱"}),
"夜雨寄北|李商隐": dict(f="君问归期未", yi="你问我回家的日期，我还定不下来；巴山的夜雨下个不停，涨满了秋天的池塘。什么时候才能和你在西窗下一起剪烛夜谈，再说说今晚巴山夜雨时的心情呢？", qing="思念亲人，盼望团聚。", ci={"巴山":"泛指巴蜀一带的山","共剪西窗烛":"一起在西窗下剪烛芯，指夜里长谈"}),
"登乐游原|李商隐": dict(f="向晚意不适", yi="傍晚心情不太舒畅，就驾车登上古老的乐游原。夕阳无限美好，只可惜已经快到黄昏了。", qing="赞美夕阳之美，也有好景不长的感叹。", ci={"向晚":"傍晚","意不适":"心情不舒畅","古原":"乐游原，在长安城南"}),
"无题|李商隐": dict(f="相见时难别", yi="见面不容易，分别更难舍，东风无力，百花凋残。春蚕到死丝才吐完，蜡烛烧成灰泪才流干。", qing="缠绵深切的思念，坚贞不渝。", ci={"丝":"与「思」谐音","蜡炬":"蜡烛","青鸟":"传说中为西王母传信的神鸟"}),
"泊秦淮|杜牧": dict(f="烟笼寒水月", yi="烟雾笼罩着寒冷的江水，月光洒在沙岸上，夜里船停在秦淮河边，靠近酒家。卖唱的歌女不懂亡国之恨，隔着江还在唱《玉树后庭花》。", qing="借古讽今，忧虑国事。", ci={"商女":"卖唱的歌女","后庭花":"《玉树后庭花》，南朝陈后主所作，被视为亡国之音"}),
"赤壁|杜牧": dict(f="折戟沉沙铁", yi="一支断戟沉在沙里还没完全锈蚀，我把它磨洗干净，认出是赤壁之战的遗物。如果东风不帮周瑜的忙，恐怕铜雀台就要锁住二乔了。", qing="借古抒怀，议论新奇。", ci={"戟":"古代兵器","周郎":"周瑜","二乔":"东吴大乔、小乔"}),
"秋夕|杜牧": dict(f="银烛秋光冷", yi="秋夜，白色的烛光映着冷清的画屏，宫女拿着小扇扑打萤火虫。夜色里的石阶凉得像水，她坐着仰望牵牛星和织女星。", qing="写宫女的孤寂与向往。", ci={"轻罗小扇":"轻薄的丝质小扇","天阶":"宫中的石阶"}),
"乌衣巷|刘禹锡": dict(f="朱雀桥边野", yi="朱雀桥边长满了野草野花，乌衣巷口夕阳斜照。当年在王导、谢安这些世家大族堂前筑巢的燕子，如今飞进了普通百姓家。", qing="感叹世事沧桑、盛衰无常。", ci={"乌衣巷":"在今南京，东晋王、谢等大族住在这里","寻常":"平常"}),
"秋词（其一）|刘禹锡": dict(f="自古逢秋悲", yi="自古以来，人们一到秋天就悲叹寂寞，我却说秋天胜过春天。晴空中一只白鹤冲破云层飞上高空，也把我的诗情带上了蓝天。", qing="一反悲秋传统，昂扬乐观。", ci={"寂寥":"寂寞冷落","排云":"冲开云层","碧霄":"青天"}),
"竹枝词|刘禹锡": dict(f="杨柳青青江", yi="杨柳青青，江水平平，听到江上传来情郎的歌声。东边出太阳，西边下着雨，说是没有晴（情）却又有晴（情）。", qing="借谐音写少女的心事，活泼含蓄。", ci={"晴":"与「情」谐音"}),
"早春呈水部张十八员外|韩愈": dict(f="天街小雨润", yi="京城街道上下着细细的小雨，像酥油一样滋润；远看草色青青，走近看却又几乎没有。这是一年中春天最好的时候，远远胜过满城烟柳的晚春。", qing="发现早春之美，充满喜悦。", bei="韩愈写给好友张籍的诗，张籍排行十八，当时任水部员外郎。", ci={"天街":"京城的街道","酥":"酥油","绝胜":"远远胜过"}),
"马诗（其五）|李贺": dict(f="大漠沙如雪", yi="大漠的沙子在月光下像雪一样白，燕山上的月亮弯得像钩。什么时候能给马戴上金络头，在秋天的原野上快快奔驰。", qing="借马抒发渴望建功立业的心情。", ci={"燕山":"在今河北北部","金络脑":"用金子装饰的马笼头"}),
"雁门太守行|李贺": dict(f="黑云压城城", yi="敌军像黑云一样压向城头，城墙好像要被摧毁；阳光照在将士的铠甲上，像金色的鱼鳞闪闪发光。将士们为报答君王的赏识，手持宝剑誓死报国。", qing="悲壮豪迈。", ci={"甲光":"铠甲反射的光","黄金台":"战国时燕昭王招纳贤士所筑"}),
"游子|孟郊": dict(f="萱草生堂阶", yi="萱草长满了堂前的台阶，游子出门远行。慈母倚着门盼望，却看不见萱草开花。", qing="写母亲盼子的深情。", ci={"萱草":"古人认为可以忘忧的草，也代指母亲"}),
"逢雪宿芙蓉山主人|刘长卿": dict(f="日暮苍山远", yi="天色晚了，苍山显得更远；天气寒冷，简陋的茅屋显得更加贫寒。柴门外传来狗叫声，是主人在风雪之夜回家了。", qing="风雪夜宿的寂寥与温暖。", ci={"白屋":"简陋的茅屋","柴门":"用树枝做的门"}),
"塞下曲（其二）|卢纶": dict(f="林暗草惊风", yi="昏暗的树林里，草忽然被风吹动，将军以为有猛虎，夜里拉弓射箭。天亮后去找那支白羽箭，发现它深深射进了石头的棱角中。", qing="赞美将军的勇猛神力。", bei="化用了汉代飞将军李广射虎的故事。", ci={"引弓":"拉弓","白羽":"箭尾的白色羽毛，指箭","没":"陷入"}),
"塞下曲（其三）|卢纶": dict(f="月黑雁飞高", yi="没有月亮的夜里，大雁飞得很高，敌军首领趁着夜色悄悄逃跑。将士正要带领轻骑兵追赶，大雪落满了弓和刀。", qing="写将士追敌的英勇和环境的艰苦。", ci={"单于":"匈奴首领，这里指敌军首领","遁":"逃跑","轻骑":"轻装快速的骑兵"}),
"别董大|高适": dict(f="千里黄云白", yi="千里黄云遮住了太阳，天色昏暗，北风吹着大雁，大雪纷纷。不要担心前路没有知己，天下谁不认识你呢？", qing="送别中充满豪情和鼓励。", bei="董大一般认为是当时著名的琴师董庭兰。", ci={"曛":"昏暗","君":"你"}),
"逢入京使|岑参": dict(f="故园东望路", yi="向东望去，回故乡的路遥远漫长，思乡的眼泪湿透了两只袖子。在马上相逢没有纸笔，只能托你带个口信回家报平安。", qing="思乡又不愿家人担心。", bei="岑参第一次出塞去安西途中遇到回长安的使者时所作。", ci={"故园":"故乡","龙钟":"湿漉漉的样子","凭":"托"}),
"白雪歌送武判官归京|岑参": dict(f="北风卷地白", yi="北风卷地，八月的塞外就飞起大雪，好像一夜春风吹来，千万棵树上开满了梨花。送朋友回京，山路弯弯，转过山就看不见他了，雪地上只留下马蹄印。", qing="塞外奇寒奇景中的惜别之情。", ci={"胡天":"塞外的天空","判官":"官职名"}),
"十五夜望月|王建": dict(f="中庭地白树", yi="庭院地面洒满月光，树上栖着乌鸦，冷露无声地打湿了桂花。今夜人人都在望月，不知道这秋天的思念落在谁家。", qing="中秋月夜的思念。", ci={"中庭":"庭院中","秋思":"秋天的思念"}),
"登鹳雀楼|畅当": None,
"长歌行|汉乐府": dict(f="青青园中葵", yi="园子里的葵菜青青，叶上的露珠等着太阳晒干。春天施下恩泽，万物都焕发光彩。常常担心秋天到来，花叶枯黄凋零。百川向东流到大海，什么时候再流回西边？年轻时不努力，老了只能白白悲伤。", qing="劝人珍惜时光、及早努力。", ci={"晞":"晒干","布德泽":"施予恩泽","焜黄":"枯黄","徒":"白白地"}),
"观沧海|曹操": dict(f="东临碣石以", yi="向东登上碣石山，来观看苍茫的大海。海水荡漾，山岛高高耸立。树木茂盛，秋风萧瑟，海上涌起巨浪。太阳月亮的运行、星河的灿烂，好像都从大海中出现。", qing="借大海的壮阔抒发远大的抱负。", bei="曹操北征乌桓胜利回师，途经碣石山时所作。", ci={"碣石":"山名","澹澹":"水波荡漾","竦峙":"高高耸立"}),
"龟虽寿|曹操": dict(f="神龟虽寿犹", yi="神龟虽然长寿，也终有尽头；腾蛇能乘云雾，最后也化为尘土。老马卧在马槽边，志向仍在千里之外；有志的人到了晚年，雄心也不会停止。", qing="老当益壮、积极进取的人生态度。", ci={"骥":"千里马","枥":"马槽","烈士":"有远大抱负的人"}),
"饮酒（其五）|陶渊明": dict(f="结庐在人境", yi="我把房子建在人来人往的地方，却听不到车马的喧闹。问我怎么做到的？心远离了尘俗，住的地方自然就清静了。在东边篱笆下采菊，悠然间看见了南山。", qing="闲适自在，超脱世俗。", ci={"结庐":"建造房屋","车马喧":"车马的喧闹","悠然":"悠闲自在"}),
"归园田居（其三）|陶渊明": dict(f="种豆南山下", yi="我在南山下种豆，杂草茂盛，豆苗稀少。清早起来去地里除草，傍晚扛着锄头踏着月光回家。小路窄，草木长，露水打湿了衣服。衣服湿了不可惜，只要不违背我的心愿就好。", qing="甘于躬耕田园的坚定心志。", ci={"荒秽":"杂草","荷锄":"扛着锄头","但使":"只要"}),
"钱塘湖春行|白居易": dict(f="孤山寺北贾", yi="从孤山寺北走到贾公亭西，湖水刚与堤岸齐平，白云低低地垂在湖面上。几处早来的黄莺争着飞向向阳的树，谁家新来的燕子在啄泥筑巢。繁花渐渐让人眼花缭乱，浅草才刚刚没过马蹄。我最爱湖东的白沙堤，绿杨成荫，怎么也走不够。", qing="陶醉于早春西湖的生机。", bei="白居易任杭州刺史时所作。", ci={"水面初平":"春水刚涨到与堤岸齐平","乱花":"各色繁花","白沙堤":"即白堤"}),
"大林寺桃花|白居易": dict(f="人间四月芳", yi="四月里，山下的花都开败了，山上寺庙里的桃花才刚刚盛开。我常常遗憾春天走了无处可寻，却不知道它转到这里来了。", qing="意外发现春天的惊喜。", ci={"芳菲":"花草","长恨":"常常遗憾"}),
"问刘十九|白居易": dict(f="绿蚁新醅酒", yi="新酿的米酒上浮着绿色的泡沫，红泥小火炉烧得正旺。天快黑了，看样子要下雪，能不能来喝一杯？", qing="邀友小饮，温暖亲切。", ci={"绿蚁":"新酒上浮的绿色泡沫","醅":"没有过滤的酒"}),
"卖炭翁|白居易": dict(f="卖炭翁伐薪", yi="卖炭的老人在南山砍柴烧炭，满脸烟灰。他衣服单薄，却盼着天更冷好卖炭。一车炭被宫里的使者用半匹红纱一丈绫强行换走了。", qing="同情劳动者，揭露宫市对百姓的掠夺。", ci={"伐薪":"砍柴","宫使":"宫里派出采买的人","直":"同「值」，价钱"}),
"水调歌头·明月几时有|苏轼": dict(f="明月几时有", yi="诗人举杯问青天：明月什么时候开始有的？想乘风回到天上，又怕高处太冷，不如在人间起舞。月亮转过楼阁，照着无眠的人。人有悲欢离合，月有阴晴圆缺，自古难以两全。只愿亲人平安长久，即使相隔千里，也能共赏这一轮明月。", qing="中秋思念弟弟，最终归于旷达。", bei="宋神宗熙宁九年中秋，苏轼在密州，怀念弟弟苏辙而作。", ci={"琼楼玉宇":"美玉砌成的楼宇，指月宫","婵娟":"美好的样子，这里指月亮"}),
"念奴娇·赤壁怀古|苏轼": dict(f="大江东去浪", yi="长江滚滚东流，浪花淘尽了千古英雄人物。想当年周瑜风度翩翩，谈笑之间，强大的曹军战船就被烧成灰烬。我神游古战场，感叹自己早生白发。人生像一场梦，还是举杯敬一敬江上的明月吧。", qing="怀古抒怀，豪放旷达。", bei="苏轼被贬黄州时，游黄州赤鼻矶所作。", ci={"樯橹":"桅杆和船桨，代指战船","酹":"把酒洒在地上祭奠"}),
"定风波·莫听穿林打叶声|苏轼": dict(f="莫听穿林打", yi="不要理会穿过树林、打在叶子上的雨声，不妨一边吟诗长啸一边慢慢走。拄竹杖穿草鞋比骑马还轻快，怕什么？披一件蓑衣，任凭风雨过一生。回头看刚才风雨萧瑟的地方，回去吧，无所谓风雨也无所谓晴。", qing="面对人生风雨的从容豁达。", bei="苏轼被贬黄州的第三年春天，途中遇雨时所作。", ci={"芒鞋":"草鞋","萧瑟":"风雨吹打树叶的声音"}),
"六月二十七日望湖楼醉书|苏轼": dict(f="黑云翻墨未", yi="乌云像打翻的墨汁，还没遮住山，白色的雨点像跳动的珍珠，乱纷纷地落进船里。忽然一阵大风卷地而来，把雨吹散了，望湖楼下的湖水又像天空一样平静。", qing="写夏日骤雨，快速而生动。", ci={"翻墨":"像打翻的墨汁","跳珠":"跳动的水珠"}),
"春宵|苏轼": dict(f="春宵一刻值", yi="春天的夜晚即使是很短的时间也价值千金，花儿散发着清香，月光朦胧。楼台上传来轻轻的歌声和音乐，秋千悬在静静的庭院里，夜已经很深了。", qing="春夜美好，也提醒人珍惜时光。", ci={"一刻":"很短的时间","沉沉":"深沉"}),
"登飞来峰|王安石": dict(f="飞来山上千", yi="飞来峰上有一座很高的塔，听说鸡叫的时候在塔上能看到太阳升起。不怕浮云遮住远望的视线，只因为我站在最高处。", qing="表达高瞻远瞩、无所畏惧的志向。", ci={"寻":"古代长度单位，八尺为一寻","缘":"因为"}),
"书湖阴先生壁|王安石": dict(f="茅檐长扫净", yi="茅草屋檐下常常打扫，干干净净，没有一点青苔；主人亲手栽种的花木成行成畦。一条小河护着农田，把绿色的禾苗环绕起来；两座山推开门，送来满眼青翠。", qing="赞美朋友居处的清幽和主人的勤劳。", ci={"湖阴先生":"作者的邻居杨德逢","排闼":"推开门"}),
"秋夜将晓出篱门迎凉有感|陆游": dict(f="三万里河东", yi="三万里长的黄河向东流入大海，五千仞高的华山直插云天。北方的百姓在金人统治下流尽了眼泪，年年向南盼望朝廷的军队。", qing="对沦陷区人民的同情，对朝廷的失望。", ci={"河":"黄河","岳":"西岳华山","胡尘":"指金人的统治","王师":"朝廷的军队"}),
"十一月四日风雨大作（其二）|陆游": dict(f="僵卧孤村不", yi="我直挺挺地躺在孤寂的乡村，并不为自己悲哀，还想着为国家守卫边疆。夜深了躺着听风吹雨打，梦见自己骑着披甲的战马跨过冰封的河流。", qing="年老体衰仍不忘报国。", ci={"僵卧":"躺卧不起","轮台":"古地名，代指边疆","铁马":"披着铁甲的战马"}),
"清平乐·村居|辛弃疾": dict(f="茅檐低小溪", yi="茅屋又低又小，溪边长满青草。一对白发老人带着醉意，用柔和的吴地口音说笑。大儿子在溪东锄豆地，二儿子在编鸡笼，最可爱的是调皮的小儿子，趴在溪边剥莲蓬。", qing="喜爱农家安宁和睦的生活。", bei="辛弃疾闲居江西上饶带湖时所作。", ci={"吴音":"吴地方言","相媚好":"彼此逗乐","无赖":"调皮"}),
"西江月·夜行黄沙道中|辛弃疾": dict(f="明月别枝惊", yi="明月升上树梢，惊飞了枝头的喜鹊；半夜清风吹来，蝉在叫。稻花香里，人们谈论着丰收的年景，耳边传来一片蛙声。天边有七八颗星星，山前下起两三点雨。从前土地庙旁树林边的茅店，转过溪桥，忽然就出现在眼前。", qing="夏夜乡村的恬静与丰收的喜悦。", ci={"别枝":"斜伸出的树枝","社林":"土地庙旁的树林"}),
"破阵子·为陈同甫赋壮词以寄之|辛弃疾": dict(f="醉里挑灯看", yi="醉中挑亮油灯看剑，梦里回到号角连营的军中。分发烤肉给部下，乐器奏出雄壮的军歌，秋天在沙场点兵。战马飞驰，弓弦惊响，想要完成君王收复失地的大业，赢得生前身后的美名——可惜，白发已经生出来了。", qing="壮志难酬的悲愤。", ci={"八百里":"牛名，这里指牛肉","的卢":"一种快马"}),
"青玉案·元夕|辛弃疾": dict(f="东风夜放花", yi="元宵夜里，满城灯火像东风吹开了千树花，又像吹落了满天星雨。笙箫声动，鱼龙灯彻夜舞动。在人群中千百次寻找她，猛然回头，那人却在灯火稀落的地方。", qing="写节日的热闹，也寄托了不随流俗的孤高。", ci={"元夕":"元宵节","蓦然":"猛然","阑珊":"零落稀少"}),
"丑奴儿·书博山道中壁|辛弃疾": dict(f="少年不识愁", yi="少年时不懂得愁是什么滋味，喜欢登高，为了写新词硬说自己愁。如今尝尽了愁的滋味，想说却说不出口，只好说：好一个凉爽的秋天啊！", qing="今昔对比，含蓄写出深沉的忧愁。", ci={"强说愁":"勉强说愁","欲说还休":"想说又停下"}),
"如梦令·常记溪亭日暮|李清照": dict(f="常记溪亭日", yi="常常想起那次在溪边亭子里游玩到傍晚，喝醉了找不到回去的路。玩够了天晚才划船回去，不小心闯进了荷花深处。拼命划呀划呀，惊起了一滩鸥鹭。", qing="回忆少女时代出游的快乐。", ci={"兴尽":"玩够了","争渡":"奋力划船","鸥鹭":"水鸟"}),
"如梦令·昨夜雨疏风骤|李清照": dict(f="昨夜雨疏风", yi="昨夜雨点稀疏，风却很猛，酣睡一夜，醉意还没消。问卷帘的侍女，她说海棠花依旧。你知道吗？应该是绿叶繁茂、红花凋零了。", qing="惜春的细腻心情。", ci={"雨疏风骤":"雨小风急","绿肥红瘦":"绿叶茂盛，红花稀少"}),
"声声慢·寻寻觅觅|李清照": dict(f="寻寻觅觅冷", yi="词人一连用了十四个叠字，写出秋天里孤独寻觅、冷清凄凉的心境，从黄昏的细雨、飞过的大雁到满地的黄花，处处都是愁。", qing="国破家亡、孤身漂泊的深重哀愁。", ci={"戚戚":"忧愁悲伤","将息":"休养调理"}),
"渔家傲·秋思|范仲淹": dict(f="塞下秋来风", yi="边塞的秋天景色和内地不同，南飞的大雁毫不留恋。四面响起边地的声音，层层山峰里，长烟落日，孤城紧闭。喝一杯浊酒，想起万里外的家乡，可是还没有建功，回家无从谈起。羌笛声悠悠，满地寒霜，将军和士兵都白了头发、流下眼泪。", qing="戍边将士的思乡和报国情怀。", bei="范仲淹在西北防御西夏时所作。", ci={"衡阳雁去":"大雁飞往衡阳","燕然未勒":"还没有建功立业"}),
"江上渔者|范仲淹": dict(f="江上往来人", yi="江上来来往往的人，只喜爱鲈鱼的鲜美。你看那一叶小小的渔船，在风浪里时隐时现。", qing="同情渔民捕鱼的艰险。", ci={"但":"只","鲈鱼":"一种味道鲜美的鱼","出没":"时隐时现"}),
"浣溪沙·一曲新词酒一杯|晏殊": dict(f="一曲新词酒", yi="听一曲新词，喝一杯酒，还是去年的天气、旧时的亭台。夕阳西下，什么时候再回来？花落去无可奈何，燕子归来却似曾相识。独自在小园花径上徘徊。", qing="感叹时光流逝，又有一丝淡淡的慰藉。", ci={"似曾相识":"好像曾经认识","香径":"花间小路"}),
"雨霖铃·寒蝉凄切|柳永": dict(f="寒蝉凄切对", yi="秋蝉叫得凄凉，傍晚在长亭，一场急雨刚停。在都城门外饯别，船家催着出发。握着手泪眼相看，说不出话来。想到这一去千里烟波，今后的良辰美景也没有人可说了。", qing="缠绵悱恻的离别之情。", ci={"长亭":"古代路边供人休息、送别的亭子","都门":"京城门外"}),
"鹊桥仙·纤云弄巧|秦观": dict(f="纤云弄巧飞", yi="借牛郎织女七夕相会的故事，说真正的感情如果长久，又何必非要天天在一起。", qing="对坚贞爱情的赞美。", ci={"纤云":"轻盈的云","朝朝暮暮":"日日夜夜"}),
"观书有感（其一）|朱熹": dict(f="半亩方塘一", yi="半亩大的方形池塘像一面打开的镜子，天光和云影在水面上一起晃动。问它为什么这样清澈？因为有源源不断的活水流进来。", qing="借池塘讲读书的道理：不断学习才能保持清明。", ci={"鉴":"镜子","渠":"它，指池塘","为有":"因为有"}),
"夜书所见|叶绍翁": dict(f="萧萧梧叶送", yi="秋风吹着梧桐叶萧萧作响，送来阵阵寒意，江上的秋风让客居他乡的人更加思乡。知道有小孩在捉蟋蟀，夜深了，篱笆边还亮着一盏灯。", qing="客中思乡，又被童趣触动。", ci={"萧萧":"风吹叶子的声音","挑":"挑弄、引动","促织":"蟋蟀"}),
"过零丁洋|文天祥": dict(f="辛苦遭逢起", yi="回想一生的辛苦，从考取功名起，到抗元已经四年。山河破碎像风吹柳絮，自己的身世像雨打浮萍。人生自古谁能不死？要留下一片赤诚之心映照史册。", qing="宁死不屈的民族气节。", bei="文天祥抗元兵败被俘，被押经零丁洋时所作。", ci={"干戈":"兵器，指战争","丹心":"赤诚的心","汗青":"史册"}),
"约客|赵师秀": dict(f="黄梅时节家", yi="梅雨时节，家家户户都在下雨，长满青草的池塘边到处是蛙声。约好的客人过了半夜还没来，我闲着无事敲着棋子，震落了灯花。", qing="等客不至的闲适与淡淡的寂寞。", ci={"黄梅时节":"梅子黄熟的时节，多雨","灯花":"油灯芯燃烧后结成的花状物"}),
"雪梅（其一）|卢梅坡": dict(f="梅雪争春未", yi="梅花和雪都争着报春，谁也不肯认输，诗人只好放下笔细细评判。梅花比雪少了三分白，雪却比梅花少了一段香。", qing="写出梅与雪各有所长。", ci={"降":"服输","阁笔":"放下笔","逊":"比不上"}),
"村晚|雷震": dict(f="草满池塘水", yi="池塘长满青草，水涨得满满的，山衔着落日，倒影浸在清凉的水波里。牧童横坐在牛背上回家，拿着短笛随意吹着，不成曲调。", qing="乡村傍晚的宁静与童趣。", ci={"陂":"池塘的岸","衔":"含着","信口":"随口"}),
"绝句·古木阴中系短篷|志南": dict(f="古木阴中系", yi="我把小船拴在古树荫下，拄着藜杖过桥向东走。杏花时节的细雨想沾湿衣服又沾不湿，吹在脸上的杨柳风一点也不冷。", qing="春日出游的惬意。", ci={"短篷":"小船","杖藜":"拄着藜杖","杨柳风":"春风"}),
"己亥杂诗（其五）|龚自珍": dict(f="浩荡离愁白", yi="离别的愁绪浩浩荡荡，夕阳西斜，我挥鞭东去，就像远在天涯。落花并不是无情的东西，化作春泥还会守护花朵。", qing="虽然离开官场，仍愿为国家贡献力量。", ci={"吟鞭":"诗人的马鞭","天涯":"天边，极远的地方"}),
"己亥杂诗（其一百二十五）|龚自珍": dict(f="九州生气恃", yi="中国要有生气，要靠风雷激荡般的变革；万马齐喑的沉闷局面实在可悲。我劝上天重新振作，不要拘泥一格地降下人才。", qing="呼唤变革和人才。", ci={"九州":"指中国","喑":"哑，不出声","抖擞":"振作"}),
"木兰诗|北朝民歌": dict(f="唧唧复唧唧", yi="木兰的父亲年老，家里没有长兄，她就女扮男装替父从军，征战十多年立下战功。回来后不要官职，只愿回到故乡，换回女装时，同行的伙伴都很吃惊。", qing="赞美木兰的勇敢、孝顺和不慕名利。", ci={"机杼":"织布机","戎机":"军机，指战事","朔气":"北方的寒气"}),
"小松|杜荀鹤": dict(f="自小刺头深", yi="松树小时候长在深草里，被埋没着，如今才渐渐高出蓬蒿。当时的人不认识它是能长成参天大树的材料，等它长到高耸入云才说它高。", qing="感叹人才在幼小时常被忽视。", ci={"刺头":"指小松树的松针","蓬蒿":"野草","凌云":"高耸入云"}),
"蜂|罗隐": dict(f="不论平地与", yi="不管是平地还是山尖，有花的地方都被蜜蜂占尽。它们采了百花酿成蜜，到底是为谁辛苦，为谁送去甜蜜呢？", qing="赞美勤劳的蜜蜂，也感叹劳动成果被他人享用。", ci={"占":"占据","尽":"全部"}),
"山亭夏日|高骈": dict(f="绿树阴浓夏", yi="绿树成荫，夏天白天很长，楼台的倒影映入池塘。水晶帘被微风吹动，一架蔷薇开满了花，满院飘香。", qing="写夏日庭院的清幽美丽。", ci={"水晶帘":"晶莹华美的帘子","蔷薇":"一种开花的灌木"}),
"春江花月夜|张若虚": dict(f="春江潮水连", yi="春江潮水连着大海，明月随潮水升起。诗人从江、月、花、夜写起，追问江畔是谁最先看见月亮、江月又是哪年最先照人，再写游子和思妇在月下彼此思念。", qing="对自然的赞叹、对人生的思索和真挚的相思。", ci={"滟滟":"水波荡漾","芳甸":"花草丛生的原野"}),
"望月怀远|张九龄": dict(f="海上生明月", yi="一轮明月从海上升起，远在天涯的亲人此时也和我一起望月。多情的人怨恨长夜漫漫，整夜不眠地相思。", qing="望月思念远方的亲人。", ci={"怀远":"怀念远方的亲人","竟夕":"整夜"}),
"滕王阁诗|王勃": None,
"登快阁|黄庭坚": None,
"山园小梅（其一）|林逋": dict(f="众芳摇落独", yi="百花凋零，只有梅花鲜艳地开着，占尽了小园的风光。稀疏的梅影横斜在清浅的水面上，淡淡的幽香在黄昏的月光下浮动。", qing="爱梅、咏梅，寄托隐士高洁的情怀。", ci={"暄妍":"鲜艳美丽","疏影":"稀疏的影子","暗香":"幽香"}),
"春日偶成|程颢": dict(f="云淡风轻近", yi="云淡风轻，快到中午了，我在花丛柳树间沿着河边走。别人不懂我心中的快乐，还以为我是忙里偷闲学少年人呢。", qing="春日出游的自得之乐。", ci={"午天":"中午","将谓":"以为"}),
"稚子弄冰|杨万里": dict(f="稚子金盆脱", yi="小孩子早上从铜盆里取出冰块，用彩线穿起来当作银钲敲。敲出的声音穿过树林，像玉磬的声音，忽然冰块碎了，发出玻璃破碎般的声响。", qing="写孩子玩冰的童趣。", ci={"稚子":"小孩","钲":"古代一种打击乐器"}),
"菊花|元稹": dict(f="秋丛绕舍似", yi="一丛丛秋菊环绕着房屋，好像到了陶渊明的家，我绕着篱笆一直看到太阳西斜。不是我偏爱菊花，而是菊花开过之后，一年里再也没有别的花可看了。", qing="对菊花的偏爱。", ci={"陶家":"陶渊明的家，陶渊明爱菊","偏":"偏偏"}),
"商山早行|温庭筠": dict(f="晨起动征铎", yi="清晨起来，车马的铃铛已经响起，远行的人怀念着故乡。鸡叫声中，茅店上挂着残月；木板桥上的霜里，印着行人的脚印。", qing="羁旅的辛苦和思乡之情。", ci={"征铎":"远行车马上的铃","茅店":"茅草盖的旅店"}),
"相见欢·无言独上西楼|李煜": dict(f="无言独上西", yi="默默无语，独自登上西楼，月亮像弯钩。梧桐寂寞地立在深院里，锁住了清冷的秋色。剪不断、理还乱的，是离别的愁绪，心头是另一种说不出的滋味。", qing="亡国之后孤独深沉的愁苦。", ci={"清秋":"冷清的秋天","离愁":"离别的忧愁"}),
"虞美人·春花秋月何时了|李煜": dict(f="春花秋月何", yi="春花秋月年年都有，往事却不堪回首。昨夜小楼又吹来东风，月光下不忍回望故国。雕栏玉砌应该还在，只是人的容颜已改。问你能有多少愁？就像一江春水向东流。", qing="亡国之痛，愁思无尽。", ci={"雕栏玉砌":"雕花栏杆和玉石台阶，指宫殿","朱颜":"红润的容颜"}),
}
N = {k: v for k, v in N.items() if v}
